const list = $input.first().json.rows || [];
const fmt = n => Number(n || 0).toLocaleString('es-ES');
const rows = list.map(p => {
  const flagBadge = p.flag_score >= 5 ? '<span style="background:#dc2626;color:white;padding:2px 6px;border-radius:3px">ATENCION</span>'
    : p.flag_score >= 2 ? '<span style="background:#f59e0b;color:white;padding:2px 6px;border-radius:3px">REVISAR</span>'
    : '<span style="background:#10b981;color:white;padding:2px 6px;border-radius:3px">OK</span>';
  const flagsTxt = [];
  if (p.pending_approvals > 0)    flagsTxt.push(p.pending_approvals + ' aprob.');
  if (p.reports_flagged_7d > 0)   flagsTxt.push(p.reports_flagged_7d + ' obra-flag');
  if (p.invoices_pending > 0)     flagsTxt.push(p.invoices_pending + ' factu.pdte');
  if (p.permits_subsanation > 0)  flagsTxt.push(p.permits_subsanation + ' subsanar');
  if (p.reg_tasks_review > 0)     flagsTxt.push(p.reg_tasks_review + ' norm.review');
  if (p.pathologies_critical > 0) flagsTxt.push('<span style="color:#7f1d1d">' + p.pathologies_critical + ' patol.crit</span>');
  else if (p.pathologies_open > 0) flagsTxt.push(p.pathologies_open + ' patol.');
  if (p.aftercare_urgent > 0)     flagsTxt.push('<span style="color:#dc2626">' + p.aftercare_urgent + ' aftercare.urg</span>');
  else if (p.aftercare_open > 0)  flagsTxt.push(p.aftercare_open + ' aftercare');
  if (p.anomalies_critical > 0)   flagsTxt.push('<span style="color:#7f1d1d">' + p.anomalies_critical + ' anomal.crit</span>');
  else if (p.anomalies_new > 0)   flagsTxt.push(p.anomalies_new + ' anomal.');
  const flags = flagsTxt.length ? '<small style="color:#dc2626">' + flagsTxt.join(' &middot; ') + '</small>' : '<small style="color:#10b981">sin alertas</small>';
  const margin = Number(p.certified || 0) - Number(p.billed || 0);
  const marginColor = margin >= 0 ? '#10b981' : '#dc2626';
  return '<tr>' +
    '<td>' + flagBadge + '</td>' +
    '<td><b>' + (p.name || '?') + '</b><br><small style="color:#6b7280">' + (p.location_city || '') + ' &middot; ' + (p.project_type || '') + '</small></td>' +
    '<td>' + (p.current_phase || '?') + '<br><small>' + Math.round(p.days_in_phase || 0) + 'd</small></td>' +
    '<td>' + (p.reports_7d || 0) + '</td>' +
    '<td>' + (p.invoices_7d || 0) + '</td>' +
    '<td>' + (p.permits_active || 0) + '</td>' +
    '<td>' + (p.estimated ? fmt(p.estimated) + 'eur' : '-') + '</td>' +
    '<td>' + fmt(p.certified) + 'eur</td>' +
    '<td>' + fmt(p.billed) + 'eur</td>' +
    '<td style="color:' + marginColor + ';font-weight:bold">' + fmt(margin) + 'eur</td>' +
    '<td>' + flags + '</td>' +
    '</tr>';
}).join('');
const attention = list.filter(p => p.flag_score >= 5).length;
const review = list.filter(p => p.flag_score >= 2 && p.flag_score < 5).length;
const html = '<h2>Resumen semanal de proyectos activos</h2>' +
  '<p>Total activos: <b>' + list.length + '</b> | Requieren atencion: <b style="color:#dc2626">' + attention + '</b> | Por revisar: <b style="color:#f59e0b">' + review + '</b></p>' +
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:12px">' +
  '<thead><tr style="background:#f3f4f6">' +
  '<th>Estado</th><th>Proyecto</th><th>Fase / dias</th><th>Reports 7d</th><th>Factu 7d</th><th>Permits</th><th>Estimado</th><th>Certificado</th><th>Facturado</th><th>Margen</th><th>Alertas</th>' +
  '</tr></thead><tbody>' + rows + '</tbody></table>' +
  '<p style="font-size:11px;color:#6b7280;margin-top:16px">Margen = certificado - facturado. Reports 7d = visitas vision. Factu 7d = OCR de facturas. Cron lunes 08:30. Trigger manual: POST /webhook/trigger-weekly-summary.</p>';
return [{ json: { html_body: html, count: list.length, attention: attention, review: review } }];

